"use client";

import * as React from "react";
import { Toast as ToastPrimitive } from "@base-ui/react/toast";
import { cva, type VariantProps } from "class-variance-authority";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { focusRing, popoverSurface, selectedLift } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Holds the toast queue, fed by the shared toast manager the Toaster passes in. */
const ToastProvider = ToastPrimitive.Provider;

/** Where toasts appear: along the bottom on a phone and in the bottom end corner from the small breakpoint. */
const ToastViewport = React.forwardRef<HTMLDivElement, WithClassName<ToastPrimitive.Viewport.Props>>(
  ({ className, ...props }, ref) => (
    <ToastPrimitive.Portal>
      <ToastPrimitive.Viewport
        ref={ref}
        data-slot="toast-viewport"
        className={cn(
          "fixed inset-x-0 bottom-0 z-100 flex flex-col gap-3 p-4 outline-none",
          "sm:start-auto sm:w-full sm:max-w-sm",
          className,
        )}
        {...props}
      />
    </ToastPrimitive.Portal>
  ),
);
ToastViewport.displayName = "ToastViewport";

/** Toast classes: a floating panel with a 0.75rem corner that rises as it fades in, with its words in red for `destructive`. */
const toastVariants = cva(
  [
    popoverSurface,
    "group pointer-events-auto relative flex w-full items-center justify-between gap-3 rounded-xl p-4 pe-12",
    "transition-[opacity,translate] duration-base ease-(--ease-out)",
    "data-[starting-style]:translate-y-2 data-[starting-style]:opacity-0",
    "data-[ending-style]:opacity-0",
    "data-[ending-style]:data-[swipe-direction=right]:translate-x-full",
    "data-[swiping]:translate-x-(--toast-swipe-movement-x) data-[swiping]:transition-none",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "",
        destructive: "text-destructive",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

/** Mallow toast: a short notice that floats over the page and leaves on its own. */
const Toast = React.forwardRef<
  HTMLDivElement,
  WithClassName<ToastPrimitive.Root.Props> & VariantProps<typeof toastVariants>
>(({ className, variant, swipeDirection = "right", ...props }, ref) => (
  <ToastPrimitive.Root
    ref={ref}
    data-slot="toast"
    data-variant={variant ?? "default"}
    swipeDirection={swipeDirection}
    className={cn(toastVariants({ variant }), className)}
    {...props}
  />
));
Toast.displayName = "Toast";

/** The toast's one follow-up action, a small violet-ringed pill at the end. */
const ToastAction = React.forwardRef<HTMLButtonElement, WithClassName<ToastPrimitive.Action.Props>>(
  ({ className, ...props }, ref) => (
    <ToastPrimitive.Action
      ref={ref}
      data-slot="toast-action"
      className={cn(
        selectedLift,
        "inline-flex h-8 shrink-0 items-center justify-center rounded-full px-3.5 text-sm font-medium",
        focusRing,
        "disabled:pointer-events-none disabled:opacity-50 data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    />
  ),
);
ToastAction.displayName = "ToastAction";

/** A small close button in the top corner of the toast. */
const ToastClose = React.forwardRef<HTMLButtonElement, WithClassName<ToastPrimitive.Close.Props>>(
  ({ className, ...props }, ref) => (
    <ToastPrimitive.Close
      ref={ref}
      data-slot="toast-close"
      aria-label="Close"
      className={cn(
        "absolute end-2.5 top-2.5 inline-flex size-7 items-center justify-center rounded-full text-muted-foreground",
        "transition-colors duration-fast ease-(--ease-out) hover:bg-accent hover:text-foreground",
        focusRing,
        className,
      )}
      {...props}
    >
      <Icon icon="iconoir:xmark" className="size-4" aria-hidden="true" />
    </ToastPrimitive.Close>
  ),
);
ToastClose.displayName = "ToastClose";

/** The toast headline in medium weight. */
const ToastTitle = React.forwardRef<HTMLHeadingElement, WithClassName<ToastPrimitive.Title.Props>>(
  ({ className, ...props }, ref) => (
    <ToastPrimitive.Title
      ref={ref}
      data-slot="toast-title"
      className={cn("text-sm font-medium leading-snug", className)}
      {...props}
    />
  ),
);
ToastTitle.displayName = "ToastTitle";

/** The detail line under the headline, in muted text. */
const ToastDescription = React.forwardRef<HTMLParagraphElement, WithClassName<ToastPrimitive.Description.Props>>(
  ({ className, ...props }, ref) => (
    <ToastPrimitive.Description
      ref={ref}
      data-slot="toast-description"
      className={cn(
        "text-sm text-muted-foreground",
        className,
      )}
      {...props}
    />
  ),
);
ToastDescription.displayName = "ToastDescription";

/** Props for one toast, as the toast store keeps them. */
type ToastProps = React.ComponentPropsWithoutRef<typeof Toast>;

/** The element type the toast store accepts as a toast's action. */
type ToastActionElement = React.ReactElement<typeof ToastAction>;

export {
  type ToastProps,
  type ToastActionElement,
  ToastProvider,
  ToastViewport,
  Toast,
  ToastTitle,
  ToastDescription,
  ToastClose,
  ToastAction,
};
